let hitPreviewTimer;const previousDiceRender=renderDiceInputs;renderDiceInputs=function(){previousDiceRender();const attack=$('#combat-attack-formula')?.textContent||'',needsAttack=state.activeParticipant?.participant_type==='character'&&/w20|waffenangriff|normaler angriff|ausweichwurf/i.test(attack);$('#hit-preview')?.classList.toggle('hidden',!needsAttack);if(needsAttack)updateHitPreview();};
async function calculateHit(){const source=state.activeSource;if(!source||state.activeParticipant?.participant_type!=='character'){notify('Trefferprüfung ist nur für Spielercharaktere verfügbar.',true);return}const body={calculation_mode:'hit',target_participant_id:$('#combat-target').value,source_type:source.source_type,source_id:source.id,damage_type:source.damage_type,actor_participant_id:state.activeParticipant.id,hit_roll:$('#hit-roll')?.value||'',target_roll:$('#target-roll')?.value||''};try{const r=await api('calculate',{method:'POST',body:JSON.stringify(body)}),a=r.attack||{};const status=a.hit===true?'TREFFER':a.hit===false?'FEHLSCHLAG':'TREFFERWURF UNVOLLSTÄNDIG';const detail=a.value==null?'Trefferwürfel fehlt':`Angriff ${a.value} gegen ${a.target_total??'—'}`;$('#calculation-result').innerHTML=`<div class="result"><div class="attack-result"><strong>${status}</strong><span>${detail}</span></div></div>`;$('#apply-row').classList.add('hidden')}catch(e){notify(e.message,true)}}
async function updateHitPreview(){const preview=$('#hit-preview'),source=state.activeSource;if(!preview||!source||state.activeParticipant?.participant_type!=='character'){return}clearTimeout(hitPreviewTimer);hitPreviewTimer=setTimeout(async()=>{const roll=$('#hit-roll')?.value||'';if(roll===''){preview.textContent='Trefferwert: —';return}try{const r=await api('calculate',{method:'POST',body:JSON.stringify({calculation_mode:'hit',source_type:source.source_type,source_id:source.id,damage_type:source.damage_type,actor_participant_id:state.activeParticipant.id,hit_roll:roll})}),a=r.attack||{};preview.textContent=`Trefferwert: ${a.value??'—'}`}catch(e){preview.textContent='Trefferwert: —'}},120)}
