// Klassenbezogene Fähigkeitsslots: Hauptklasse zwei Slots je Freischaltungsstufe,
// jede Nebenklasse einen Slot. Die Rolle wird mit jedem Slot gespeichert.
function multiclassAbilityDefinitions(){const f=$('#character-form');if(!f)return[];const rows=[['primary','primary_class_id','primary_class_level'],['secondary_1','secondary_class_1_id','secondary_class_1_level'],['secondary_2','secondary_class_2_id','secondary_class_2_level']];return rows.map(([role,classField,levelField])=>{const id=String(f.elements[classField]?.value||'');const level=Math.max(1,Math.floor(Number(f.elements[levelField]?.value)||1));const classRow=state.classes.find(c=>String(c.id)===id);return{role,id,level,name:classRow?.name||id,slots:role==='primary'?2:1}}).filter(row=>row.id)}
function multiclassAbilityIsOrigin(){return String($('#character-form')?.elements.primary_class_id?.value||'').toLowerCase().includes('ursprungsvermaechtnis')}
function multiclassSelectedAbilityIds(){const ids=[];Object.values(state.abilitySlots||{}).forEach(levels=>Object.values(levels||{}).forEach(slots=>Object.values(slots||{}).forEach(id=>{if(id)ids.push(String(id))})));return ids}
function renderMulticlassAbilities(rows){const options=$('#ability-options');if(!options)return;const query=String($('#ability-search')?.value||'').toLowerCase();state.currentAbilities=rows;const defs=multiclassAbilityDefinitions();if(multiclassAbilityIsOrigin()){const primary=defs.find(def=>def.role==='primary'),groups={};rows.filter(a=>+a.unlock_level<=(primary?.level||+$('[name=level]').value||1)&&(!query||String(a.name).toLowerCase().includes(query))).forEach(a=>(groups[a.unlock_level]??=[]).push(a));state.abilitySlots={};state.selectedAbilities.clear();const levels=Object.keys(groups).sort((a,b)=>a-b).map(level=>`<fieldset class="ability-level origin-ability-level"><legend>Stufe ${level}</legend>${groups[level].map(a=>`<article class="origin-ability"><strong>${esc(a.name)}</strong><small>${esc(a.type||'Fähigkeit')} · automatisch verfügbar</small></article>`).join('')}</fieldset>`).join('');options.innerHTML=`<section class="ability-class-box" data-ability-class-role="primary"><h5>${esc(primary?.name||'Hauptklasse')}</h5>${levels||'<p class="field-hint">Für diese Stufe sind keine Fähigkeiten hinterlegt.</p>'}</section>`;return}
const boxes=[];for(const def of defs){const groups={},fieldsets=[];rows.filter(a=>a._classRole===def.role&&+a.unlock_level<=def.level&&(!query||String(a.name).toLowerCase().includes(query))).forEach(a=>(groups[a.unlock_level]??=[]).push(a));Object.keys(groups).sort((a,b)=>a-b).forEach(level=>{const slotMarkup=Array.from({length:def.slots},(_,index)=>{const slot=index+1,selected=String(state.abilitySlots?.[def.role]?.[level]?.[slot]||''),choices=groups[level].map(a=>`<option value="${esc(a.id)}" ${selected===String(a.id)?'selected':''}>${esc(a.name)}</option>`).join('');return`<label>Slot ${slot}<select data-ability-role="${esc(def.role)}" data-ability-slot-level="${level}" data-ability-slot="${slot}"><option value="">Fähigkeit wählen</option>${choices}</select></label>`}).join('');fieldsets.push(`<fieldset class="ability-level"><legend>Stufe ${level}</legend>${slotMarkup}</fieldset>`)});boxes.push(`<section class="ability-class-box" data-ability-class-role="${esc(def.role)}"><h5>${esc(def.name)}</h5>${fieldsets.join('')||'<p class="field-hint">Für diese Stufe sind keine Fähigkeiten hinterlegt.</p>'}</section>`)}
options.innerHTML=boxes.join('')||'<p class="option">Bitte zuerst eine Hauptklasse auswählen.</p>';$$('[data-ability-role]').forEach(select=>select.onchange=()=>{const role=select.dataset.abilityRole,level=select.dataset.abilitySlotLevel,slot=select.dataset.abilitySlot;state.abilitySlots[role]??={};state.abilitySlots[role][level]??={};state.abilitySlots[role][level][slot]=select.value;state.selectedAbilities=new Set(multiclassSelectedAbilityIds())})}
let multiclassAbilityLoadSerial=0;async function loadMulticlassAbilities(){const serial=++multiclassAbilityLoadSerial,defs=multiclassAbilityDefinitions(),nextClassIds=Object.fromEntries(defs.map(def=>[def.role,def.id]));state._abilityClassIds??={};Object.keys(state._abilityClassIds).forEach(role=>{if(!nextClassIds[role]){state.abilitySlots[role]={};delete state._abilityClassIds[role]}});defs.forEach(def=>{if(state._abilityClassIds[def.role]&&state._abilityClassIds[def.role]!==def.id)state.abilitySlots[def.role]={};state._abilityClassIds[def.role]=def.id;Object.keys(state.abilitySlots[def.role]||{}).forEach(level=>{if(+level>def.level)delete state.abilitySlots[def.role][level]})});state.selectedAbilities=new Set(multiclassSelectedAbilityIds());if(!defs.length){state.currentAbilities=[];state.abilitySlots={};state.selectedAbilities.clear();renderMulticlassAbilities([]);return}try{const rows=[];for(const def of defs){const abilities=await api(`classes/${encodeURIComponent(def.id)}/abilities?level=${def.level}`);abilities.forEach(ability=>rows.push({...ability,_classRole:def.role,_classId:def.id,_classLevel:def.level}))}if(serial!==multiclassAbilityLoadSerial)return;renderMulticlassAbilities(rows)}catch(error){notify(error.message,true)}}
loadAbilities=loadMulticlassAbilities;renderAbilities=renderMulticlassAbilities;
const multiclassAbilityFieldNames=new Set(['primary_class_id','primary_class_level','secondary_class_1_id','secondary_class_1_level','secondary_class_2_id','secondary_class_2_level']);document.addEventListener('input',event=>{if(multiclassAbilityFieldNames.has(event.target?.name))loadMulticlassAbilities()});document.addEventListener('change',event=>{if(multiclassAbilityFieldNames.has(event.target?.name))loadMulticlassAbilities()});

// Bestehende Charaktere in die rollenbezogene Slotstruktur übernehmen.
const editCharacterWithMulticlassSlots=editCharacter;editCharacter=async function(id){await editCharacterWithMulticlassSlots(id);const c=await api(`characters/${id}`),f=$('#character-form');state.abilitySlots={};(c.abilities||[]).forEach(ability=>{const role=ability.class_role||'primary',level=String(ability.ability_level||ability.unlock_level),slot=String(ability.slot_number||1);state.abilitySlots[role]??={};state.abilitySlots[role][level]??={};if(!state.abilitySlots[role][level][slot])state.abilitySlots[role][level][slot]=ability.id});state.selectedAbilities=new Set(multiclassSelectedAbilityIds());state._abilityClassIds=Object.fromEntries(multiclassAbilityDefinitions().map(def=>[def.role,def.id]));await loadMulticlassAbilities();renderSpells();if(f)f.classList.remove('hidden')};
